const tabId = 730410078;
const delegatedListeners = await browserjs(tabId, () => {
  const $ = window.jQuery || window.$;
  const docEvents = $ ? $._data(document, 'events') : null;
  const bodyEvents = $ ? $._data(document.body, 'events') : null;
  const pageContentEvents = $ ? $._data(document.getElementById('page_content'), 'events') : null;
  const chartControlsEvents = $ ? $._data(document.getElementById('chart_controls'), 'events') : null;

  function summarize(events) {
    if (!events) return null;
    const res = {};
    for (const [k, v] of Object.entries(events)) {
      res[k] = v.map(e => ({ selector: e.selector, namespace: e.namespace }));
    }
    return res;
  }

  return {
    document: summarize(docEvents),
    body: summarize(bodyEvents),
    pageContent: summarize(pageContentEvents),
    chartControls: summarize(chartControlsEvents)
  };
});
console.log(JSON.stringify(delegatedListeners, null, 2));

