const tabId = 730410078;
const searchScripts = await browserjs(tabId, async () => {
  const scripts = Array.from(document.querySelectorAll('script'));
  const results = [];
  for (const s of scripts) {
    if (s.src) {
      try {
        const res = await fetch(s.src);
        const text = await res.text();
        if (text.includes('scale_toggle') || text.includes('chart_controls') || text.includes('accordion')) {
          results.push({ src: s.src, len: text.length, snippet: text.slice(text.indexOf('scale_toggle') - 50, text.indexOf('scale_toggle') + 200) });
        }
      } catch (e) {
        results.push({ src: s.src, error: e.message });
      }
    } else {
      if (s.text.includes('scale_toggle') || s.text.includes('chart_controls') || s.text.includes('accordion')) {
        results.push({ inline: true, snippet: s.text.slice(0, 300) });
      }
    }
  }
  return results;
});
console.log(JSON.stringify(searchScripts, null, 2));

