const tabId = 730410078;
const comparisonData = await browserjs(tabId, () => {
  if (typeof g === 'undefined') return { error: "g not found" };

  const labels = g.getLabels();
  const numRows = g.numRows();
  const visibility = g.visibility();
  const logscale = g.getOption('logscale');

  // Let's get summary stats for Price Quartile 1 (col index 5 in raw data, since col 0 is Date) and Price Quartile 4 (col index 8)
  // Let's verify which column index corresponds to Quartile 1 and 4 of Price
  // Note: li id="4" and id="7" were used: g.setVisibility("4", true) etc.
  // In Dygraph, series index is 0-based. li id corresponds to series index 4 and 7.
  // In raw data row: [Date, Series 0, Series 1, ..., Series 15]

  const seriesNames = labels.slice(1);
  const q1Name = seriesNames[4];
  const q4Name = seriesNames[7];

  let q1Min = Infinity, q1Max = -Infinity, q1Sum = 0, q1Count = 0;
  let q4Min = Infinity, q4Max = -Infinity, q4Sum = 0, q4Count = 0;

  const samples = [];

  for (let i = 0; i < numRows; i++) {
    const date = new Date(g.getValue(i, 0)).toISOString().slice(0, 10);
    const q1Val = g.getValue(i, 5); // col 0 is date, col 5 is series 4
    const q4Val = g.getValue(i, 8); // col 8 is series 7

    if (q1Val !== null && !isNaN(q1Val)) {
      q1Min = Math.min(q1Min, q1Val);
      q1Max = Math.max(q1Max, q1Val);
      q1Sum += q1Val;
      q1Count++;
    }
    if (q4Val !== null && !isNaN(q4Val)) {
      q4Min = Math.min(q4Min, q4Val);
      q4Max = Math.max(q4Max, q4Val);
      q4Sum += q4Val;
      q4Count++;
    }

    if (i === 0 || i === Math.floor(numRows / 4) || i === Math.floor(numRows / 2) || i === Math.floor(numRows * 3 / 4) || i === numRows - 1) {
      samples.push({ date, q1Val, q4Val });
    }
  }

  return {
    labels,
    visibility,
    logscale,
    q1Name,
    q4Name,
    numRows,
    startDate: new Date(g.getValue(0, 0)).toISOString().slice(0, 10),
    endDate: new Date(g.getValue(numRows - 1, 0)).toISOString().slice(0, 10),
    q1Stats: {
      min: q1Min,
      max: q1Max,
      avg: q1Sum / q1Count,
      latest: g.getValue(numRows - 1, 5)
    },
    q4Stats: {
      min: q4Min,
      max: q4Max,
      avg: q4Sum / q4Count,
      latest: g.getValue(numRows - 1, 8)
    },
    samples
  };
});
console.log(JSON.stringify(comparisonData, null, 2));

